import{_ as t,a,o as n,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"adminAppearanceSectionPreview","description":"","frontmatter":{"outline":false,"apiType":"graphql","examples":[{"id":"basic","title":"Preview","query":"query preview($code: String!, $channel: Int, $locale: String) {\\n  adminAppearanceSectionPreview(code: $code, channel: $channel, locale: $locale) {\\n    themeCode\\n    channelId\\n    locale\\n    sections\\n  }\\n}\\n","variables":"{\\n  \\"code\\": \\"default\\",\\n  \\"channel\\": 1,\\n  \\"locale\\": \\"en\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminAppearanceSectionPreview\\": {\\n      \\"themeCode\\": \\"default\\",\\n      \\"channelId\\": 1,\\n      \\"locale\\": \\"en\\",\\n      \\"sections\\": [\\n        {\\n          \\"id\\": 3,\\n          \\"name\\": \\"Categories Collections\\",\\n          \\"type\\": \\"category_carousel\\",\\n          \\"sortOrder\\": 1,\\n          \\"status\\": true,\\n          \\"hasDraft\\": false,\\n          \\"options\\": { \\"filters\\": { \\"sort\\": \\"asc\\", \\"limit\\": \\"10\\" } }\\n        },\\n        {\\n          \\"id\\": 15,\\n          \\"name\\": \\"Summer Sale\\",\\n          \\"type\\": \\"static_content\\",\\n          \\"sortOrder\\": 2,\\n          \\"status\\": true,\\n          \\"hasDraft\\": true,\\n          \\"options\\": { \\"html\\": \\"<h2>Summer sale</h2>\\", \\"css\\": \\".sale { color: #c00; }\\" }\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/appearance/sections/preview.md","filePath":"api/graphql-api/admin/appearance/sections/preview.md","lastUpdated":1789385991000}'),s={name:"api/graphql-api/admin/appearance/sections/preview.md"};function r(d,e,i,c,l,h){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="adminappearancesectionpreview" tabindex="-1">adminAppearanceSectionPreview <a class="header-anchor" href="#adminappearancesectionpreview" aria-label="Permalink to &quot;adminAppearanceSectionPreview&quot;">​</a></h1><p>The sections a channel would draw if its staged edits were published: draft content replaces published content, staged status and order are applied, sections that are off are left out, and <code>footer_links</code> stays last.</p><p>A headless storefront renders this to show a merchant their unpublished work. The storefront&#39;s own <a href="/api/graphql-api/shop/sections/list.html">sections</a> query never returns staged content, which is why the preview lives on the admin side and needs an admin token.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td><code>String!</code></td><td>Theme being previewed.</td></tr><tr><td><code>channel</code></td><td><code>Int</code></td><td>Channel being previewed. Falls back to the current channel.</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale the content is read in. Falls back to the channel locale.</td></tr></tbody></table><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>themeCode</code></td><td><code>String</code></td><td>Theme that was previewed.</td></tr><tr><td><code>channelId</code></td><td><code>Int</code></td><td>Channel that was previewed.</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale the content was read in.</td></tr><tr><td><code>sections</code></td><td><code>Iterable</code></td><td>Sections in the order they would be drawn, each <code>{ id, name, type, sortOrder, status, hasDraft, options }</code>.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Render an unpublished storefront page</strong> — the list is ready to draw in order, each section&#39;s content already resolved for the locale.</li><li><strong>Show what publishing would change</strong> — compare each entry&#39;s <code>hasDraft</code> against the published <a href="/api/graphql-api/admin/appearance/sections/list.html">adminAppearanceSections</a>.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Query <code>sections</code> bare.</strong> It is a JSON value and takes no sub-selection.</li><li><strong>Sections staged off do not appear at all</strong> — the preview is what shoppers would see, so do not use it to build the editor&#39;s list.</li><li><strong>A section with no staged edits is returned with its published values</strong>, so the preview is complete even when only one section was touched.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.sections</code>.</p>',13)]))}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
